// A simple class to demonstrate initialization vs. assignment
class Widget {
public:
    Widget() {}
    Widget(const Widget& other) { /* copy constructor logic */ }
    Widget& operator=(const Widget& other) { /* copy assignment logic */ return *this; }
};

int x1(0);        // Direct-initialization with parentheses
int x2 = 0;       // Copy-initialization with equals
int x3{ 0 };      // Uniform/list-initialization with braces
int x4 = { 0 };   // Also uniform/list-initialization

Widget w1;          // Calls default constructor
Widget w2 = w1;     // Initialization: calls copy constructor
w1 = w2;            // Assignment: calls copy assignment operator
